using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t; cin >> t;
    while (t--) {
        long long n; cin >> n;
        // From the problem and examples:
        // For n=1 -> 1 way
        // For n=2 -> 2 ways
        // For n=3 -> 3 ways (implied)
        // So the answer is simply n
        cout << n << "\n";
    }
    return 0;
}

