#include <iostream>
#include <string>
using namespace std;

int main() {
    int n; cin >> n;
    string s; cin >> s;
    string res;
    for (int i = 0; i < n;) {
        if (i + 2 < n && s[i] == 'o' && s[i+1] == 'g' && s[i+2] == 'o') {
            int j = i + 3;
            while (j + 1 < n && s[j] == 'g' && s[j+1] == 'o') {
                j += 2;
            }
            res += "***";
            i = j;
        } else {
            res += s[i];
            i++;
        }
    }
    cout << res << "\n";
    return 0;
}

