#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll N, X, M;
    cin >> N >> X >> M;

    vector<ll> A;
    vector<int> pos(M, -1);

    ll cur = X;
    ll sum = 0;
    int idx = 0;
    while (idx < N && pos[cur] == -1) {
        pos[cur] = idx;
        A.push_back(cur);
        sum += cur;
        cur = (cur * cur) % M;
        idx++;
    }

    if (idx == N) {
        cout << sum << "\n";
        return 0;
    }

    int start = pos[cur];
    int cycle_len = idx - start;

    ll pre_sum = 0;
    for (int i = 0; i < start; i++) pre_sum += A[i];

    ll cycle_sum = 0;
    for (int i = start; i < idx; i++) cycle_sum += A[i];

    ll rem = N - start;
    ll q = rem / cycle_len;
    ll r = rem % cycle_len;

    ll ans = pre_sum + cycle_sum * q;
    for (int i = 0; i < r; i++) ans += A[start + i];

    cout << ans << "\n";

    return 0;
}

